P = {}
P['papa-paulus-3'] = dict(name='Pope Paul III', cat='The pope who opened Trent', born='Canino',
 bio='He approved the Jesuit Order and called the Council of Trent, the most important council of the Catholic Reformation.',
 secs=[['The Jesuits', 'In 1540 he formally approved the Society of Jesus (the Jesuits), founded by Ignatius of Loyola and his companions.'],
       ['The Council of Trent', 'After the Protestant Reformation he called the Council of Trent in 1545. The council set out the Catholic faith clearly and renewed the Church deeply, from the training of priests to the liturgy.'],
       ['The Last Judgement', 'He had Michelangelo paint the Last Judgement on the altar wall of the Sistine Chapel.']],
 docs=[['Regimini Militantis Ecclesiae', '1540', 'The approval of the Jesuit Order.']])
P['papa-pius-4'] = dict(name='Pope Pius IV', cat='The pope who completed the Council of Trent', born='Milan',
 bio='He reopened the Council of Trent, which had been suspended for ten years, and brought it to a successful close in 1563.',
 secs=[['Trent', 'The council set out clearly the Catholic teaching on Scripture and Tradition, the sacraments and justification, and called for seminaries to train candidates for the priesthood. Pius confirmed its decrees in 1564.'],
       ['St. Charles Borromeo', 'He brought his nephew Charles Borromeo to work beside him. Charles became a great bishop who put the council’s decrees into practice, and a saint.']],
 docs=[['Professio fidei Tridentina', '1564', 'The profession of faith used after the Council of Trent.']])
P['papa-pius-5'] = dict(name='Pope Pius V', cat='The rosary pope · Saint', born='Bosco (Italy)',
 bio='He was a Dominican friar and kept wearing the white Dominican habit as pope; the popes’ custom of wearing white is said to come from him. He credited the victory at Lepanto to the rosary.',
 secs=[['Putting Trent into practice', 'He put the decrees of the Council of Trent into effect: the Roman Catechism (1566), the revised Breviary (1568) and the Roman Missal of 1570 were published in his time. That Missal was used for almost four hundred years.'],
       ['Lepanto and the rosary', 'In 1571 he formed a Holy League against the Ottoman fleet and called all Christians to pray the rosary. After the victory at Lepanto on 7 October 1571 he declared that day the feast of “Our Lady of Victory”; today it is celebrated as the feast of Our Lady of the Rosary.'],
       ['His link to Turkey', 'The Battle of Lepanto was the Ottoman Empire’s first great defeat at sea. The Catholic world credited the victory to the rosary; the story of the battle is told on the History of the Rosary page.']],
 docs=[['Consueverunt Romani Pontifices', '1569', 'Set the rosary in its present form.'],
       ['Quo Primum', '1570', 'Promulgated the Roman Missal for the whole Latin Church.']])
P['papa-gregorius-13'] = dict(name='Pope Gregory XIII', cat='The pope of the calendar', born='Bologna',
 bio='The calendar used by almost the whole world today bears his name: the Gregorian calendar.',
 secs=[['Calendar reform', 'Over the centuries the Julian calendar had fallen about ten days behind the true solar year, and the date of Easter was drifting. The new calendar Gregory had scientists prepare came into force in 1582: the day after Thursday 4 October was Friday 15 October.'],
       ['Education', 'He enlarged the Jesuit college in Rome; today, as the Pontifical Gregorian University, it bears his name.'],
       ['His link to Turkey', 'Turkey adopted the Gregorian calendar on 1 January 1926. The dates we use today rest on the calculations made in his time.']],
 docs=[['Inter Gravissimas', '1582', 'The papal bull that brought in the Gregorian calendar.']])
P['papa-sixtus-5'] = dict(name='Pope Sixtus V', cat='The pope who rebuilt Rome', born='Grottammare',
 bio='A shepherd boy who became a Franciscan. In five years he reshaped Rome’s streets, aqueducts and squares; the dome of St. Peter’s was completed in his time.',
 secs=[['The dome and the obelisk', 'In 1586 he had the obelisk brought from Egypt raised in the middle of St. Peter’s Square. In 1590 the dome designed by Michelangelo was completed by Giacomo della Porta.'],
       ['Cardinals and congregations', 'He limited the number of cardinals to seventy and divided the government of the Vatican into fifteen congregations. This arrangement was used for centuries.']],
 docs=[['Immensa Aeterni Dei', '1588', 'The constitution that divided the Roman Curia into congregations.']])
P['papa-urbanus-8'] = dict(name='Pope Urban VIII', cat='Bernini’s pope · the pope of the Galileo affair', born='Florence',
 bio='A portrait of him as a young man is attributed to Caravaggio; as pope he commissioned Bernini’s magnificent baldachin in St. Peter’s Basilica. The Galileo affair took place in his time.',
 secs=[['A pope of the arts', 'Maffeo Barberini consecrated the new St. Peter’s Basilica in 1626. Bernini’s bronze baldachin and the Palazzo Barberini are works of his time.'],
       ['Galileo', 'At first he was a friend of Galileo; but after his “Dialogue” was published in 1632, Galileo was tried in 1633 and sentenced to house arrest. In 1992, in a speech by John Paul II, the Church acknowledged the errors made in the case.']],
 docs=[])
P['papa-innocentius-11'] = dict(name='Pope Innocent XI', cat='The pope of simple living · Blessed', born='Como',
 bio='He lived very simply himself and cut back extravagance in the Vatican. The siege of Vienna in 1683 happened during his papacy.',
 secs=[['Simplicity', 'He ended the habit of handing out offices and wealth to relatives and reduced the debts of the Papal States. He was beatified in 1956.'],
       ['Vienna 1683', 'When the Ottoman army besieged Vienna he backed the alliance between King Jan Sobieski of Poland and Emperor Leopold I and sent great help. The lifting of the siege is remembered as a turning point in European history.']],
 docs=[])
P['papa-benedictus-14'] = dict(name='Pope Benedict XIV', cat='The pope of the first encyclical', born='Bologna',
 bio='He was one of the most learned jurists of his day. Ubi Primum, issued in the first year of his papacy, is counted as the first encyclical in the modern sense.',
 secs=[['The path to sainthood', 'The great work he wrote before becoming pope set out in detail the steps for declaring someone blessed and a saint; its rules were used for a long time.'],
       ['Science and friendship', 'He corresponded with scientists and supported the universities. He was respected even among Protestants.']],
 docs=[['Ubi Primum', '1740', 'To the bishops on their duties; the first encyclical in the modern sense.']])
P['papa-clemens-14'] = dict(name='Pope Clement XIV', cat='The pope who suppressed the Jesuits', born='Santarcangelo di Romagna',
 bio='He was a Franciscan priest. Under pressure from the kings of Europe he suppressed the Jesuit Order in 1773; he founded the Pio-Clementine Museum in the Vatican.',
 secs=[['The Jesuits', 'The kings of Portugal, Spain and France wanted the Jesuits abolished. After long hesitation, in 1773 Clement suppressed the order with “Dominus ac Redemptor”. The order was restored in 1814 by Pius VII.'],
       ['The museum', 'To display ancient statues he founded the Pio-Clementine Museum, the core of today’s Vatican Museums.']],
 docs=[['Dominus ac Redemptor', '1773', 'The papal brief that suppressed the Jesuit Order.']])
P['papa-pius-7'] = dict(name='Pope Pius VII', cat='Napoleon’s prisoner', born='Cesena',
 bio='He signed an agreement with Napoleon and attended his coronation, then spent five years as his prisoner.',
 secs=[['Napoleon', 'The Concordat he signed with France in 1801 allowed the Church to live openly in France again after the Revolution. In 1804 he was present in Paris at Napoleon’s coronation as emperor.'],
       ['Captivity', 'When he opposed Napoleon’s annexation of the Papal States in 1809 he was arrested and held prisoner in Savona and Fontainebleau until 1814. Once free he returned to Rome, and that same year he restored the Jesuit Order.']],
 docs=[])
P['papa-gregorius-16'] = dict(name='Pope Gregory XVI', cat='The pope against the slave trade', born='Belluno',
 bio='He was a Camaldolese monk, and the last pope elected who was not yet a bishop. He openly condemned the slave trade.',
 secs=[['Slavery', 'With “In supremo apostolatus” in 1839 he expressly forbade Christians to enslave Africans and other peoples and to take part in the slave trade.'],
       ['The missions', 'He founded new dioceses all over the world and encouraged the training of local clergy. In his time the missions in Asia, Africa and the Americas grew greatly.']],
 docs=[['In supremo apostolatus', '1839', 'The apostolic letter condemning the slave trade.'],
       ['Mirari vos', '1832', 'An encyclical on the currents of thought of the time.']])
P['papa-pius-9'] = dict(name='Pope Pius IX', cat='The longest papacy · Blessed', born='Senigallia',
 bio='His papacy of more than 31 years is the longest that can be verified historically. He defined the Immaculate Conception as a truth of faith and called the First Vatican Council.',
 secs=[['The Immaculate Conception', 'In 1854 he defined as a truth of faith that Mary was preserved from original sin from the moment of her conception. Four years later Mary, appearing at Lourdes, introduced herself with the words “I am the Immaculate Conception”.'],
       ['The First Vatican Council', 'The council held in 1869-1870 defined that the pope is infallible when he formally teaches on faith and morals. That same year the Papal States were absorbed into Italy, and Pius regarded himself as “the prisoner of the Vatican”.'],
       ['Beatification', 'He was beatified by John Paul II in 2000.']],
 docs=[['Ineffabilis Deus', '1854', 'The Immaculate Conception of Mary.'],
       ['Quanta Cura and the Syllabus', '1864', 'Warnings against the currents of thought of the time.'],
       ['Pastor Aeternus', '1870', 'The First Vatican Council: the infallibility of the pope.']])
